/// `childIterator` helps walk through children based on a bitmask.
struct ChildIter<'a> {
    indices: &'a [usize],
    pos: usize,
}

impl<'a> ChildIter<'a> {
    fn new(indices: &'a [usize]) -> ChildIter<'a> {
        ChildIter { indices, pos: 0 }
    }

    /// `it.next()` — the next child index, advancing the position (0 = nil).
    fn next(&mut self) -> usize {
        if self.pos >= self.indices.len() {
            return 0;
        }
        let ci = self.indices[self.pos];
        self.pos += 1;
        ci
    }

    /// `it.nextIf(mask, bit)` — the index of the next child if the
    /// corresponding mask bit is set.
    fn next_if(&mut self, mask: u8, bit: u8) -> usize {
        if mask & (1 << bit) == 0 {
            return 0;
        }
        self.next()
    }
}

/// `d.nodeAt(ci)` — index 0 is the nil sentinel.
fn node_at(decoded: &[Option<NodeId>], ci: usize) -> Option<NodeId> {
    if ci == 0 {
        return None;
    }
    decoded[ci]
}

/// `d.nodeListAt(ci)`
///
/// PORT: Go shares `*ast.NodeList` pointers; the port clones the owned
/// `NodeList` (a `Box<[NodeId]>` copy).
fn node_list_at(node_lists: &[Option<NodeList>], ci: usize) -> Option<NodeList> {
    if ci == 0 {
        return None;
    }
    node_lists[ci].clone()
}

/// `d.getModifierList`/`d.modifierListAt` — creates a `ModifierList` from a
/// child index that is a NodeList.
fn modifier_list_at(
    factory: &tsc_ast::NodeFactory,
    arena: &[tsc_ast::Node],
    node_lists: &[Option<NodeList>],
    ci: usize,
) -> Option<tsc_ast::ModifierList> {
    if ci == 0 {
        return None;
    }
    let nl = node_lists[ci].clone()?;
    let mut ml = factory.new_modifier_list(arena, nl.nodes.to_vec());
    ml.loc = nl.loc;
    Some(ml)
}

/// `d.singleChild(childIndices)`
fn single_child(decoded: &[Option<NodeId>], child_indices: &[usize]) -> Option<NodeId> {
    child_indices.first().and_then(|&ci| decoded[ci])
}

/// `d.singleNodeListChild(childIndices)`
fn single_node_list_child(
    node_lists: &[Option<NodeList>],
    child_indices: &[usize],
) -> Option<NodeList> {
    child_indices.first().and_then(|&ci| node_lists[ci].clone())
}

/// `d.allocNodeSlice` — Go batch-allocates `[]*ast.Node` from an arena and
/// returns a zero-length slice which callers `append` to (or, for
/// SyntaxList/JSDocTypeLiteral, index-assign into — see the PORT comments on
/// those cases).
fn alloc_node_slice(capacity: usize) -> Vec<Option<NodeId>> {
    Vec::with_capacity(capacity)
}

/// `d.createStringNode`
pub(crate) fn create_string_node(
    d: &mut AstDecoder,
    kind: Kind,
    data: u32,
    common_data: u8,
) -> Result<NodeId, DecodeError> {
    let str_idx = data & NODE_DATA_STRING_INDEX_MASK;
    let text = d.get_string_text(str_idx);

    match kind {
        Kind::Identifier => Ok(d.factory.new_identifier(&mut d.arena, &text)),
        Kind::PrivateIdentifier => Ok(d.factory.new_private_identifier(&mut d.arena, &text)),
        Kind::JsxText => {
            let contains_only_trivia_white_spaces = common_data & 1 != 0;
            Ok(d.factory
                .new_jsx_text(&mut d.arena, &text, contains_only_trivia_white_spaces))
        }
        Kind::JSDocText => Ok(d.factory.new_js_doc_text(&mut d.arena, &[text])),
        Kind::JSDocLink => Ok(d.factory.new_js_doc_link(&mut d.arena, None, &[text])),
        Kind::JSDocLinkPlain => Ok(d.factory.new_js_doc_link_plain(&mut d.arena, None, &[text])),
        Kind::JSDocLinkCode => Ok(d.factory.new_js_doc_link_code(&mut d.arena, None, &[text])),
        _ => Err(DecodeError::new(format!(
            "unknown string node kind {kind:?}"
        ))),
    }
}

/// `d.createExtendedNode`
pub(crate) fn create_extended_node(
    d: &mut AstDecoder,
    kind: Kind,
    data: u32,
    child_indices: &[usize],
    common_data: u8,
) -> Result<NodeId, DecodeError> {
    match kind {
        Kind::StringLiteral => Ok(d.decode_extended_data_string_literal(data)),
        Kind::NumericLiteral => Ok(d.decode_extended_data_numeric_literal(data)),
        Kind::BigIntLiteral => Ok(d.decode_extended_data_big_int_literal(data)),
        Kind::RegularExpressionLiteral => {
            Ok(d.decode_extended_data_regular_expression_literal(data))
        }
        Kind::NoSubstitutionTemplateLiteral => {
            Ok(d.decode_extended_data_no_substitution_template_literal(data))
        }
        Kind::TemplateHead => Ok(d.decode_extended_data_template_head(data)),
        Kind::TemplateMiddle => Ok(d.decode_extended_data_template_middle(data)),
        Kind::TemplateTail => Ok(d.decode_extended_data_template_tail(data)),
        Kind::SourceFile => d.decode_extended_data_source_file(data, child_indices, common_data),
        _ => Err(DecodeError::new(format!(
            "unknown extended data node kind {kind:?}"
        ))),
    }
}

